css:
@page {
    size: A4;
    margin: 0;
}
html, body {
    margin: 0;
    padding: 0;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
    font-family: "Times New Roman", serif;
}
.print-format {
    margin-top: 46mm;
    margin-bottom: 30mm;
    margin-left: 20mm;
    margin-right: 20mm;
    padding: 0;
    width: 210mm;
}
@media print {
    .print-format {
        margin: 0 !important;
        padding: 0 !important;
    }
}
.page {
    position: relative;
    width: 210mm;
    min-height: auto;
    box-sizing: border-box;
    overflow: visible;
}
.page .bg {
    position: fixed;
    top: 0;
    left: 0;
    width: 210mm;
    height: 297mm;
    z-index: 0;
    display: block;
    object-fit: fill;
}
.page .content {
    position: relative;
    z-index: 1;
    box-sizing: border-box;
    font-family: "Times New Roman", serif;
    font-size: 14px;
    line-height: 1.5;
    text-align: justify;
    word-wrap: break-word;
    overflow-wrap: break-word;
    white-space: normal;
    color: #000;
}
@supports (display: grid) {
    .page .content {
        padding-top: 46mm;
        padding-bottom: 30mm;
        padding-left: 20mm;
        padding-right: 20mm;
        box-decoration-break: clone;
        -webkit-box-decoration-break: clone;
    }
}
.content h2 {
    margin: 0 0 16px 0;
    font-size: 18px;
    font-weight: bold;
    text-align: center;
    letter-spacing: 0.4px;
    font-family: "Times New Roman", serif;
}
.content p {
    margin: 0 0 14px 0;
    font-size: 14px;
    line-height: 1.5;
    text-indent: 0;
    font-family: "Times New Roman", serif;
    orphans: 3;
    widows: 3;
}
.details { margin-bottom: 16px; }
.details p { margin: 0 0 5px 0; text-indent: 0; font-size: 14px; font-family: "Times New Roman", serif; }
.signature {
    margin-top: 40px;
    page-break-inside: avoid;
    break-inside: avoid;
    font-family: "Times New Roman", serif;
    font-size: 14px;
}
.signature img {
    width: 130px;
    max-width: 140px;
    height: auto;
    display: block;
    margin-bottom: 6px;
}
.signature p { background: transparent; }
.letter-head, #header-html, #footer-html { display: none !important; }
